// Supplied board API (copied starter API). Learners do not edit this file.
// It serves the shared reference board definition exactly as stored in board-reference.json.
// The Node development server (tools/serve.mjs) starts this process and forwards /api/* to it.

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

var boardFile = Path.Combine(AppContext.BaseDirectory, "board-reference.json");
var release = "w2-06-supplied";
var environment = Environment.GetEnvironmentVariable("LAB_ENV") ?? "local";

// Every response carries the contract headers (see source/shared/contract/API-CONTRACT.md).
app.Use(async (context, next) =>
{
    context.Response.Headers["X-Lab-Release"] = release;
    context.Response.Headers["X-Lab-Environment"] = environment;
    context.Response.Headers["X-Request-Id"] = Guid.NewGuid().ToString("N");
    await next();
});

// GET only: the API returns the board definition, never a running game session.
app.MapGet("/api/boards/reference", () =>
    Results.Text(File.ReadAllText(boardFile), "application/json; charset=utf-8"));

app.MapGet("/api/boards/{id}", (string id) =>
    Results.Json(new { code = "NOT_FOUND", message = "Board not found" }, statusCode: 404));

app.MapGet("/healthz", () => Results.Text("Healthy"));

app.Run();
